body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: #1a1a1a;
    color: #e0e0e0;
    line-height: 1.6;
}

main {
    min-height: 100vh;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

h1 {
    font-size: 2rem;
    margin-bottom: 2rem;
    color: #ffffff;
    text-align: center;
}

.details {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.example {
    background-color: #2d2d2d;
    border: 1px solid #404040;
    border-radius: 8px;
    transition: all 0.2s ease;
}

.example:hover {
    border-color: #505050;
    background-color: #333333;
}

.example h2 {
    margin: 0;
}

.example button {
    width: 100%;
    padding: 1.25rem;
    background: none;
    border: none;
    color: #ffffff;
    font-size: 1rem;
    font-weight: 500;
    text-align: left;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: color 0.2s ease;
}

.example button:hover {
    color: #4db8ff;
}

.example button:focus {
    outline: 2px solid #4db8ff;
    outline-offset: 2px;
}

.example button::after {
    content: '▼';
    font-size: 0.75rem;
    transition: transform 0.3s ease;
    flex-shrink: 0;
    margin-left: 1rem;
}

.example button[aria-expanded="true"]::after {
    transform: rotate(180deg);
}

.example > div {
    max-height: 1000px;
    overflow: hidden;
    transition: all 0.3s ease, padding 0.3s ease;
    padding: 0 1.25rem 1.25rem 1.25rem;
}

.example > div[hidden] {
    display: none;
}

.example > div p {
    color: #d0d0d0;
    margin: 0;
}

/* Ensure good contrast for all text */
@media (prefers-contrast: more) {
    body {
        background-color: #000000;
        color: #ffffff;
    }

    .example {
        background-color: #1a1a1a;
        border-color: #666666;
    }

    .example button:hover {
        color: #66ccff;
    }

    .example button:focus {
        outline-color: #66ccff;
    }
}

/* Respect reduced motion preference */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    .example button::after {
        transition: none;
    }

    .example > div {
        transition: none;
    }
}

/* Responsive design */
@media (max-width: 600px) {
    .container {
        padding: 1rem 0.5rem;
    }

    h1 {
        font-size: 1.5rem;
        margin-bottom: 1.5rem;
    }

    .example button {
        padding: 1rem;
        font-size: 0.95rem;
    }

    .example > div {
        padding: 0 1rem 1rem 1rem;
    }
}
